from watcher_runtime import harness
from watcher_runtime.adapters import parcel_dhl

TRACKING = "00340434161094042557"
DEADLINE = "2026-10-02T16:00:00Z"

try:
    parcel = parcel_dhl.fetch(TRACKING)
except Exception:
    harness.fail("I couldn't reach DHL tracking just now.")
else:
    if parcel.get("delivered"):
        harness.emit("resolved", "Your parcel was delivered.", "DHL",
                     {"status": parcel.get("status")}, fear_came_true=False)
    elif not parcel.get("found"):
        harness.emit("ok", "DHL doesn't list the parcel yet.", "DHL", next_check_s=3600)
    elif harness.hours_until(DEADLINE) < 6:
        harness.emit("act_now", "Parcel still not delivered and the deadline is close.", "DHL",
                     {"status": parcel.get("status")}, next_check_s=1800)
    else:
        harness.emit("ok", "Parcel is on its way.", "DHL",
                     {"status": parcel.get("status")}, next_check_s=3600)
