try:
    forecast = weather_openmeteo.fetch(52.52, 13.405)
except Exception:
    harness.fail("I couldn't read the forecast just now.")
else:
    day = [d for d in forecast["daily"] if d.get("date") == DAY]
    if not day:
        harness.emit("ok", "The day is not in the forecast yet.", "Open-Meteo", next_check_s=21600)
    elif (day[0].get("precipitation_mm") or 0) >= 5:
        harness.emit("act_now", "Rain is forecast for the day. Maybe plan a backup.",
                     "Open-Meteo", {"precipitation_mm": day[0]["precipitation_mm"]},
                     next_check_s=21600)
